CREATE TABLE cmdb_ire_runs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL, source_id BIGINT UNSIGNED NOT NULL, created_by BIGINT UNSIGNED NOT NULL, executor_id BIGINT UNSIGNED NOT NULL, idempotency_key VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, payload_hash BINARY(32) NOT NULL, mode ENUM('INCREMENTAL','FULL') NOT NULL, snapshot_scope VARCHAR(255) NOT NULL DEFAULT '', complete_snapshot BOOLEAN NOT NULL DEFAULT FALSE, state ENUM('QUEUED_DRY_RUN','DRY_RUN','QUEUED_APPLY','APPLYING','COMPLETED','PARTIAL','FAILED','CANCELLED') NOT NULL DEFAULT 'QUEUED_DRY_RUN', rule_versions JSON NOT NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, error_code VARCHAR(80) NOT NULL DEFAULT '', created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), finished_at DATETIME(6) NULL, UNIQUE KEY cmdb_ire_run_key(tenant_id,source_id,idempotency_key), UNIQUE KEY cmdb_ire_run_tenant_id(tenant_id,id), KEY cmdb_ire_run_list(tenant_id,state,id), KEY cmdb_ire_run_source(tenant_id,source_id,id), CONSTRAINT cmdb_ire_run_source FOREIGN KEY(tenant_id,source_id) REFERENCES cmdb_ire_sources(tenant_id,id), CONSTRAINT cmdb_ire_run_creator FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT cmdb_ire_run_executor FOREIGN KEY(executor_id) REFERENCES users(id), CONSTRAINT cmdb_ire_run_completion CHECK(NOT complete_snapshot OR mode='FULL')) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
